// Строим COQL-запрос к Zoho Deals с учётом query-параметров ?limit= и ?search=
const q = $json.query || {};
let limit = parseInt(q.limit, 10);
if (!Number.isFinite(limit) || limit <= 0) limit = 200;
limit = Math.min(limit, 200);
const search = String(q.search || '').replace(/['%\\]/g, '').trim().slice(0, 60);
let where = 'Created_Time is not null';
if (search) {
  where += ` and (Deal_Name like '%${search}%' or Phone like '%${search}%' or Lead_Source like '%${search}%' or Stage like '%${search}%')`;
}
const select_query = `select Deal_Name, Phone, Stage, Lead_Source, Created_Time, Zip_Code, Best_Contact_Time, Description, Contact_Name.First_Name, Contact_Name.Last_Name, Contact_Name.Email, Contact_Name.Mailing_State from Deals where ${where} order by Created_Time desc limit ${limit}`;
return [{ json: { select_query } }];

// Приводим ответ COQL к плоскому массиву лидов для дашборда
const resp = $input.first().json || {};
const q = $('Webhook').first().json.query || {};
let rows = Array.isArray(resp.data) ? resp.data : [];
let error = '';
if (!Array.isArray(resp.data) && Object.keys(resp).length > 0) {
  if (resp.message || resp.code) error = ('Zoho: ' + (resp.code || '') + ' ' + (resp.message || '')).trim();
}
// COQL может вернуть lookup-поля как "Contact_Name.First_Name" или вложенным объектом
const g = (r, k) => {
  if (r[k] !== undefined && r[k] !== null) return r[k];
  let v = r;
  for (const p of k.split('.')) v = (v && typeof v === 'object') ? v[p] : undefined;
  return v == null ? '' : v;
};
let leads = rows.map(r => {
  let added = '';
  if (r.Created_Time) {
    const dt = DateTime.fromISO(r.Created_Time).setZone('America/New_York');
    added = dt.isValid ? dt.toFormat('yyyy-MM-dd HH:mm') : String(r.Created_Time);
  }
  let first = g(r, 'Contact_Name.First_Name') || '';
  let last = g(r, 'Contact_Name.Last_Name') || '';
  if (!first && !last && r.Deal_Name) {
    const parts = String(r.Deal_Name).trim().split(/\s+/);
    first = parts.shift() || '';
    last = parts.join(' ');
  }
  return {
    added,
    first_name: first,
    last_name: last,
    phone: r.Phone || '',
    email: g(r, 'Contact_Name.Email') || '',
    city: g(r, 'Contact_Name.Mailing_State') || '',
    zip: r.Zip_Code || '',
    contact_time: r.Best_Contact_Time || '',
    source: r.Lead_Source || '',
    status: r.Stage || '',
    deal_stage: r.Stage || '',
    deal_id: r.id || '',
    via_dashboard: /Added via Dashboard/i.test(String(r.Description || '')),
  };
});
// Подстраховка: фильтр/лимит на нашей стороне (COQL уже применил своё)
const search = String(q.search || '').trim().toLowerCase();
if (search) leads = leads.filter(l => JSON.stringify(l).toLowerCase().includes(search));
const limit = parseInt(q.limit, 10);
if (Number.isFinite(limit) && limit > 0) leads = leads.slice(0, limit);

return [{ json: { ok: !error, error, count: leads.length, leads } }];
